FUNCTION_BLOCK FB_sCO2_Brayton_TurbocompressorSurge
(*
======================================================================================================
  LUMINA CYBER-PHYSICAL SYSTEMS ARCHITECTURE - HIGH-RELIABILITY AEROSPACE / POWER GENERATION
  COMPONENT: Supercritical CO2 (sCO2) Closed-Loop Brayton Power Cycle Turbocompressor
  TAG: FB-sCO2-CMP-ASV-PCHE-01
  CLASSIFICATION: IEC 61131-3 Standard Safety & Critical Process Automation Engine
  FUNCTION: 
    - 2oo3 Triple Modular Redundant (TMR) Multi-Sensor Fusion & Fault-Tolerant Voting
    - High-Pressure Centrifugal Turbocompressor Aerodynamic Surge Prevention & Fast Dynamic Recirculation
    - Span-Wagner Thermodynamic Real-Gas EOS Approximation Near sCO2 Critical Point (30.98 deg C, 73.77 bar)
    - Proactive dP/dt & dm/dt Surge Anticipation Derivative Derivative-Kick Injection
    - State-Space Model Predictive Observer & Multivariable LQ Optimal Valve Coordination
    - Diffusion-Bonded Printed Circuit Heat Exchanger (PCHE) Core Differential & Thermal Shock Bypass
    - Graceful Sensor Degradation Strategy (3oo3 -> 2oo3 -> 1oo2 -> Fail-Safe Trip)
======================================================================================================
*)
VAR_INPUT
    (* Supervisory Execution & Hardware Interlocks *)
    bEnable                 : BOOL;     (* Master supervisory cycle enable command [Active TRUE] *)
    bEStop_SIL3             : BOOL;     (* Safety Instrumented System (SIS) SIL-3 hardwired trip relay [Active TRUE] *)
    bManualOverride         : BOOL;     (* HMI operator manual bypass control takeover command [Active TRUE] *)
    rManualASV_Demand       : REAL;     (* Operator manual demand for anti-surge recirculation valve CV-101 [0.0..100.0 %] *)
    rManualPCHE_Demand      : REAL;     (* Operator manual demand for PCHE thermal stress bypass valve CV-202 [0.0..100.0 %] *)

    (* 2oo3 Redundant Suction Pressure Transducers PT-101 *)
    rP_Suction_PT101A       : REAL;     (* Turbocompressor suction absolute pressure channel A [bar] *)
    rP_Suction_PT101B       : REAL;     (* Turbocompressor suction absolute pressure channel B [bar] *)
    rP_Suction_PT101C       : REAL;     (* Turbocompressor suction absolute pressure channel C [bar] *)

    (* 2oo3 Redundant Discharge Pressure Transducers PT-102 *)
    rP_Discharge_PT102A     : REAL;     (* Turbocompressor discharge absolute pressure channel A [bar] *)
    rP_Discharge_PT102B     : REAL;     (* Turbocompressor discharge absolute pressure channel B [bar] *)
    rP_Discharge_PT102C     : REAL;     (* Turbocompressor discharge absolute pressure channel C [bar] *)

    (* 2oo3 Redundant Compressor Inlet Fluid Temperature RTDs TT-101 *)
    rT_Inlet_TT101A         : REAL;     (* Supercritical fluid inlet temperature channel A [deg C] *)
    rT_Inlet_TT101B         : REAL;     (* Supercritical fluid inlet temperature channel B [deg C] *)
    rT_Inlet_TT101C         : REAL;     (* Supercritical fluid inlet temperature channel C [deg C] *)

    (* 2oo3 Redundant Main Loop Coriolis/Venturi Mass Flow Meters FT-101 *)
    rM_Flow_FT101A          : REAL;     (* Core turbocompressor inlet mass flow channel A [kg/s] *)
    rM_Flow_FT101B          : REAL;     (* Core turbocompressor inlet mass flow channel B [kg/s] *)
    rM_Flow_FT101C          : REAL;     (* Core turbocompressor inlet mass flow channel C [kg/s] *)

    (* 2oo3 Redundant High-Speed Optical / Magnetic Tachometers ST-101 *)
    rRotorSpeed_ST101A      : REAL;     (* Turbomachine high-speed rotor velocity channel A [rpm] *)
    rRotorSpeed_ST101B      : REAL;     (* Turbomachine high-speed rotor velocity channel B [rpm] *)
    rRotorSpeed_ST101C      : REAL;     (* Turbomachine high-speed rotor velocity channel C [rpm] *)

    (* 2oo3 Redundant Bearing Proximity Shaft Vibration Sensors VT-101 *)
    rVib_Radial_VT101A      : REAL;     (* High-pressure radial bearing displacement/velocity channel A [mm/s] *)
    rVib_Radial_VT101B      : REAL;     (* High-pressure radial bearing displacement/velocity channel B [mm/s] *)
    rVib_Radial_VT101C      : REAL;     (* High-pressure radial bearing displacement/velocity channel C [mm/s] *)

    (* Printed Circuit Heat Exchanger Core Instrumentation *)
    rPCHE_Core_DeltaP_PDT201: REAL;     (* Diffusion-bonded microchannel recuperator core differential pressure [bar] *)
    rPCHE_Core_WallTemp_TT205: REAL;    (* PCHE diffusion-bonded solid matrix metal core temperature [deg C] *)
    rCycle_ThermalLoad_KW   : REAL;     (* Brayton cycle gross thermal power thermal input [kW] *)

    (* Task Timing Parameter *)
    tScanPeriod             : TIME;     (* Deterministic cycle execution period, e.g. T#10MS *)
END_VAR

VAR_OUTPUT
    (* Final Control Element Actuator Demands *)
    rRecircValveDemand      : REAL;     (* High-speed anti-surge recirculation valve CV-101 analog command [0.0..100.0 %] *)
    rPcheBypassDemand       : REAL;     (* PCHE microchannel thermal stress bypass valve CV-202 command [0.0..100.0 %] *)

    (* Aerodynamic & Thermodynamic State Observers *)
    rSurgeMargin            : REAL;     (* Instantaneous normalized aerodynamic surge margin distance S_m [%] *)
    rPressureRatio          : REAL;     (* 2oo3 voted total compressor pressure ratio Pi = P_dis / P_suc [-] *)
    rEffectiveSpeed         : REAL;     (* 2oo3 voted and filtered shaft rotational speed [rpm] *)
    rEffectiveMassFlow      : REAL;     (* 2oo3 voted and compensated fluid mass flow rate [kg/s] *)
    rEffectiveVibration     : REAL;     (* 2oo3 voted peak bearing radial vibration velocity [mm/s] *)
    rPcheThermalGradient    : REAL;     (* Microchannel matrix thermal transient rate dT/dt [deg C/min] *)
    rFluidDensity_Inlet     : REAL;     (* Calculated sCO2 density at compressor inlet suction [kg/m^3] *)
    rCompressibility_Z      : REAL;     (* Calculated real-gas compressibility factor Z near critical point [-] *)

    (* System Health, Diagnostics & Protection Words *)
    wTMR_SensorHealth       : WORD;     (* 2oo3 instrumentation channel discrepancy and failure bitmask *)
    dwStatusWord            : DWORD;    (* Subsystem state machine, control mode, and operational status word *)
    dwAlarmWord             : DWORD;    (* Comprehensive safety interlock, surge violation, and trip alarm bitmask *)
    bTripInterlock          : BOOL;     (* Emergency Turbocompressor Master Safety Trip Command [Active TRUE] *)
    bSystemReady            : BOOL;     (* Subsystem armed, healthy, and operational ready status [Active TRUE] *)
END_VAR

VAR
    (* Internal State Machine Variables *)
    iState                  : INT := 0; (* Primary finite state machine execution pointer *)
    iPreviousState          : INT := 0; (* Latching previous state for transition edge detection *)
    tStateTimer             : TON;      (* Step dwell accumulator timer *)

    (* 2oo3 TMR Redundant Voting Intermediate Storage *)
    rVoted_P_Suction        : REAL;     (* Filtered 2oo3 suction pressure [bar] *)
    rVoted_P_Discharge      : REAL;     (* Filtered 2oo3 discharge pressure [bar] *)
    rVoted_T_Inlet          : REAL;     (* Filtered 2oo3 inlet temperature [deg C] *)
    rVoted_M_Flow           : REAL;     (* Filtered 2oo3 mass flow rate [kg/s] *)
    rVoted_Speed            : REAL;     (* Filtered 2oo3 shaft rotational speed [rpm] *)
    rVoted_Vib              : REAL;     (* Filtered 2oo3 bearing vibration [mm/s] *)

    (* Sensor Discrepancy Failure Flags *)
    bFail_P_Suc_A           : BOOL;
    bFail_P_Suc_B           : BOOL;
    bFail_P_Suc_C           : BOOL;
    bFail_P_Dis_A           : BOOL;
    bFail_P_Dis_B           : BOOL;
    bFail_P_Dis_C           : BOOL;
    bFail_T_In_A            : BOOL;
    bFail_T_In_B            : BOOL;
    bFail_T_In_C            : BOOL;
    bFail_M_Fl_A            : BOOL;
    bFail_M_Fl_B            : BOOL;
    bFail_M_Fl_C            : BOOL;
    bFail_Speed_A           : BOOL;
    bFail_Speed_B           : BOOL;
    bFail_Speed_C           : BOOL;
    bFail_Vib_A             : BOOL;
    bFail_Vib_B             : BOOL;
    bFail_Vib_C             : BOOL;

    (* Dynamic Surge Line & Limit Constants *)
    rSurgeFlowLimit         : REAL;     (* Parabolic aerodynamic stall mass flow boundary [kg/s] *)
    rSurgeControlFlow       : REAL;     (* Safety-biased Surge Control Line (SCL) target flow [kg/s] *)
    rSurgeMarginBias        : REAL;     (* Speed-dependent safety margin delta [%] *)
    rSafetyMarginTarget     : REAL := 15.0; (* Standard nominal design safety margin percentage [%] *)

    (* Fast Derivative Surge Anticipation (dP/dt and dm/dt) *)
    rPrevPressureRatio      : REAL := 1.0;
    rPrevMassFlow           : REAL := 0.0;
    rRate_dPi_dt            : REAL := 0.0; (* Time derivative of pressure ratio [1/s] *)
    rRate_dm_dt             : REAL := 0.0; (* Time derivative of mass flow rate [kg/s^2] *)
    bSurgeAnticipateActive  : BOOL := FALSE;
    rSurgeKickHoldVal       : REAL := 0.0;
    tSurgeKickDecayTimer    : TON;

    (* State-Space Model Predictive Controller (MPC) Matrices & Vectors (3-State, 2-Input, 2-Output) *)
    (* State x = [x1: Delta-Pressure_Ratio, x2: Core_Flow_Error, x3: PCHE_Thermal_Error]^T *)
    (* Input u = [u1: ASV_Demand, u2: PCHE_Bypass_Demand]^T *)
    rState_x1               : REAL := 0.0;
    rState_x2               : REAL := 0.0;
    rState_x3               : REAL := 0.0;
    rStateHat_x1            : REAL := 0.0;
    rStateHat_x2            : REAL := 0.0;
    rStateHat_x3            : REAL := 0.0;

    (* Discrete State Transition Matrix A_d (Ts = 10ms) *)
    a11 : REAL := 0.9412;  a12 : REAL := -0.0185; a13 : REAL := 0.0000;
    a21 : REAL := 0.0824;  a22 : REAL :=  0.8950; a23 : REAL := -0.0041;
    a31 : REAL := 0.0000;  a32 : REAL :=  0.0120; a33 : REAL :=  0.9850;

    (* Discrete Input Control Matrix B_d *)
    b11 : REAL := -0.0520; b12 : REAL :=  0.0015;
    b21 : REAL :=  0.1140; b22 : REAL := -0.0850;
    b31 : REAL := -0.0025; b32 : REAL :=  0.0630;

    (* Luenberger Observer Gain Matrix L *)
    l11 : REAL := 0.2240;  l12 : REAL := 0.0150;
    l21 : REAL := 0.1850;  l22 : REAL := 0.3120;
    l31 : REAL := 0.0050;  l32 : REAL := 0.0980;

    (* Linear Quadratic Regulator Optimal Gain Matrix K *)
    k11 : REAL := -2.450;  k12 : REAL :=  4.120;  k13 : REAL := -0.150;
    k21 : REAL :=  0.320;  k22 : REAL := -1.850;  k23 : REAL :=  3.450;

    (* Controller Demands *)
    rMPC_ASV_Demand         : REAL := 0.0;
    rMPC_PCHE_Demand        : REAL := 0.0;
    rPID_ASV_Integral       : REAL := 0.0;
    rPID_PCHE_Integral      : REAL := 0.0;

    (* PCHE Thermal Gradient Tracking *)
    rPrev_PCHE_WallTemp     : REAL := 25.0;
    rFilteredThermalGrad    : REAL := 0.0;
    rPcheCoreDeltaP_Filtered: REAL := 0.0;

    (* Real-Gas Span-Wagner Approximation Coefficients for sCO2 *)
    rT_Critical_K           : REAL := 304.13;   (* Critical Temperature T_c = 30.98 deg C in Kelvin *)
    rP_Critical_Bar         : REAL := 73.773;   (* Critical Pressure P_c = 73.773 bar *)
    rGasConstant_R          : REAL := 188.92;   (* Specific Gas Constant for CO2 [J/(kg*K)] *)

    (* Timers & Diagnostic Utilities *)
    tDiscrepancyFilter      : TON;
    tDegradedHoldTimer      : TON;
    tTripDelayTimer         : TON;
    rDt_Seconds             : REAL := 0.010;    (* Default time step delta in seconds *)
END_VAR

(*
======================================================================================================
  ALARM WORD (dwAlarmWord) BIT DEFINITIONS:
    Bit 00 (0x00000001): HARD_ESTOP_TRIPPED - Safety Instrumented System SIL-3 Relay Open
    Bit 01 (0x00000002): SUCTION_PRESS_LOW_TRIP - Suction Pressure < 74.0 bar (Two-Phase Liquid Risk)
    Bit 02 (0x00000004): DISCHARGE_PRESS_HIGH_TRIP - Discharge Pressure > 285.0 bar (Rupture Hazard)
    Bit 03 (0x00000008): INLET_TEMP_LOW_TRIP - Inlet Temperature < 31.0 deg C (Condensation Surge)
    Bit 04 (0x00000010): RADIAL_VIBRATION_WARN - Shaft Radial Vibration > 4.5 mm/s
    Bit 05 (0x00000020): RADIAL_VIBRATION_TRIP - Shaft Radial Vibration > 7.1 mm/s (Bearing Destruction)
    Bit 06 (0x00000040): SURGE_MARGIN_CRITICAL - Margin to Surge Line S_m < 3.0 % (Active Aerodynamic Stall)
    Bit 07 (0x00000080): FAST_SURGE_ANTICIPATION - Rapid Dynamic dP/dt Surge Transient Injected
    Bit 08 (0x00000100): PCHE_DELTAP_HIGH_WARN - Heat Exchanger Core Delta-P > 3.8 bar
    Bit 09 (0x00000200): PCHE_DELTAP_HIGH_TRIP - Heat Exchanger Core Delta-P > 4.8 bar (Delamination Risk)
    Bit 10 (0x00000400): PCHE_THERMAL_SHOCK_WARN - Core Matrix |dT/dt| > 2.5 deg C / min
    Bit 11 (0x00000800): TMR_DISCREPANCY_DETECTED - Sensor Variance Deviation Across 2oo3 Channels
    Bit 12 (0x00001000): TMR_DEGRADED_MODE_ACTIVE - Single Channel Failed, Running 1oo2 Mean Selection
    Bit 13 (0x00002000): TMR_CRITICAL_SENSOR_LOSS - Dual Channel Failure, Fallback 1oo1 Single Channel
    Bit 14 (0x00004000): MANUAL_OVERRIDE_ENABLED - HMI Operator Direct Manual Valve Modulation Active
    Bit 15 (0x00008000): ASV_VALVE_TRACKING_FAULT - CV-101 Feedback Deviation from Setpoint Demand
======================================================================================================
*)

(* --- EXECUTION INITIALIZATION & TIME SCAN CONVERSION --- *)
IF TIME_TO_REAL(tScanPeriod) > 0.0 THEN
    rDt_Seconds := TIME_TO_REAL(tScanPeriod) / 1000.0;
ELSE
    rDt_Seconds := 0.010; (* 10 millisecond fallback safety scan step *)
END_IF;

(* ---------------------------------------------------------------------------------------------------
   STAGE 1: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & SENSOR FAULT DETECTOR
   Performs median selection across 3 channels. Detects out-of-band drift, calculates discrepancy,
   and implements graceful degradation from 2oo3 -> 1oo2 -> 1oo1 -> Trip.
   --------------------------------------------------------------------------------------------------- *)
wTMR_SensorHealth := 16#0000;

(* --- Suction Pressure Transducer 2oo3 Voting (PT-101A/B/C) --- *)
bFail_P_Suc_A := (rP_Suction_PT101A < 10.0) OR (rP_Suction_PT101A > 150.0);
bFail_P_Suc_B := (rP_Suction_PT101B < 10.0) OR (rP_Suction_PT101B > 150.0);
bFail_P_Suc_C := (rP_Suction_PT101C < 10.0) OR (rP_Suction_PT101C > 150.0);

IF (ABS(rP_Suction_PT101A - rP_Suction_PT101B) > 3.0) OR (ABS(rP_Suction_PT101B - rP_Suction_PT101C) > 3.0) THEN
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0001; (* Deviation Flag *)
END_IF;

IF (NOT bFail_P_Suc_A) AND (NOT bFail_P_Suc_B) AND (NOT bFail_P_Suc_C) THEN
    (* 3-Channel Healthy Median Selection *)
    IF ((rP_Suction_PT101A >= rP_Suction_PT101B) AND (rP_Suction_PT101A <= rP_Suction_PT101C)) OR 
       ((rP_Suction_PT101A <= rP_Suction_PT101B) AND (rP_Suction_PT101A >= rP_Suction_PT101C)) THEN
        rVoted_P_Suction := rP_Suction_PT101A;
    ELSIF ((rP_Suction_PT101B >= rP_Suction_PT101A) AND (rP_Suction_PT101B <= rP_Suction_PT101C)) OR 
          ((rP_Suction_PT101B <= rP_Suction_PT101A) AND (rP_Suction_PT101B >= rP_Suction_PT101C)) THEN
        rVoted_P_Suction := rP_Suction_PT101B;
    ELSE
        rVoted_P_Suction := rP_Suction_PT101C;
    END_IF;
ELSIF (NOT bFail_P_Suc_A) AND (NOT bFail_P_Suc_B) THEN
    rVoted_P_Suction := (rP_Suction_PT101A + rP_Suction_PT101B) * 0.5;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0002; (* Degraded 1oo2 *)
ELSIF (NOT bFail_P_Suc_B) AND (NOT bFail_P_Suc_C) THEN
    rVoted_P_Suction := (rP_Suction_PT101B + rP_Suction_PT101C) * 0.5;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0002;
ELSIF (NOT bFail_P_Suc_A) AND (NOT bFail_P_Suc_C) THEN
    rVoted_P_Suction := (rP_Suction_PT101A + rP_Suction_PT101C) * 0.5;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0002;
ELSIF (NOT bFail_P_Suc_A) THEN
    rVoted_P_Suction := rP_Suction_PT101A;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0004; (* Critical 1oo1 *)
ELSIF (NOT bFail_P_Suc_B) THEN
    rVoted_P_Suction := rP_Suction_PT101B;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0004;
ELSIF (NOT bFail_P_Suc_C) THEN
    rVoted_P_Suction := rP_Suction_PT101C;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0004;
ELSE
    rVoted_P_Suction := 75.0; (* Failsafe boundary default *)
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0008; (* Total Instrument Loss *)
END_IF;

(* --- Discharge Pressure Transducer 2oo3 Voting (PT-102A/B/C) --- *)
bFail_P_Dis_A := (rP_Discharge_PT102A < 30.0) OR (rP_Discharge_PT102A > 320.0);
bFail_P_Dis_B := (rP_Discharge_PT102B < 30.0) OR (rP_Discharge_PT102B > 320.0);
bFail_P_Dis_C := (rP_Discharge_PT102C < 30.0) OR (rP_Discharge_PT102C > 320.0);

IF (ABS(rP_Discharge_PT102A - rP_Discharge_PT102B) > 5.0) OR (ABS(rP_Discharge_PT102B - rP_Discharge_PT102C) > 5.0) THEN
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0010;
END_IF;

IF (NOT bFail_P_Dis_A) AND (NOT bFail_P_Dis_B) AND (NOT bFail_P_Dis_C) THEN
    IF ((rP_Discharge_PT102A >= rP_Discharge_PT102B) AND (rP_Discharge_PT102A <= rP_Discharge_PT102C)) OR 
       ((rP_Discharge_PT102A <= rP_Discharge_PT102B) AND (rP_Discharge_PT102A >= rP_Discharge_PT102C)) THEN
        rVoted_P_Discharge := rP_Discharge_PT102A;
    ELSIF ((rP_Discharge_PT102B >= rP_Discharge_PT102A) AND (rP_Discharge_PT102B <= rP_Discharge_PT102C)) OR 
          ((rP_Discharge_PT102B <= rP_Discharge_PT102A) AND (rP_Discharge_PT102B >= rP_Discharge_PT102C)) THEN
        rVoted_P_Discharge := rP_Discharge_PT102B;
    ELSE
        rVoted_P_Discharge := rP_Discharge_PT102C;
    END_IF;
ELSIF (NOT bFail_P_Dis_A) AND (NOT bFail_P_Dis_B) THEN
    rVoted_P_Discharge := (rP_Discharge_PT102A + rP_Discharge_PT102B) * 0.5;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0020;
ELSIF (NOT bFail_P_Dis_B) AND (NOT bFail_P_Dis_C) THEN
    rVoted_P_Discharge := (rP_Discharge_PT102B + rP_Discharge_PT102C) * 0.5;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0020;
ELSIF (NOT bFail_P_Dis_A) AND (NOT bFail_P_Dis_C) THEN
    rVoted_P_Discharge := (rP_Discharge_PT102A + rP_Discharge_PT102C) * 0.5;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0020;
ELSIF (NOT bFail_P_Dis_A) THEN
    rVoted_P_Discharge := rP_Discharge_PT102A;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0040;
ELSIF (NOT bFail_P_Dis_B) THEN
    rVoted_P_Discharge := rP_Discharge_PT102B;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0040;
ELSIF (NOT bFail_P_Dis_C) THEN
    rVoted_P_Discharge := rP_Discharge_PT102C;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0040;
ELSE
    rVoted_P_Discharge := 220.0;
    wTMR_SensorHealth := wTMR_SensorHealth OR 16#0080;
END_IF;

(* --- Inlet Temperature Transducer 2oo3 Voting (TT-101A/B/C) --- *)
bFail_T_In_A := (rT_Inlet_TT101A < 15.0) OR (rT_Inlet_TT101A > 120.0);
bFail_T_In_B := (rT_Inlet_TT101B < 15.0) OR (rT_Inlet_TT101B > 120.0);
bFail_T_In_C := (rT_Inlet_TT101C < 15.0) OR (rT_Inlet_TT101C > 120.0);

IF (NOT bFail_T_In_A) AND (NOT bFail_T_In_B) AND (NOT bFail_T_In_C) THEN
    IF ((rT_Inlet_TT101A >= rT_Inlet_TT101B) AND (rT_Inlet_TT101A <= rT_Inlet_TT101C)) OR 
       ((rT_Inlet_TT101A <= rT_Inlet_TT101B) AND (rT_Inlet_TT101A >= rT_Inlet_TT101C)) THEN
        rVoted_T_Inlet := rT_Inlet_TT101A;
    ELSIF ((rT_Inlet_TT101B >= rT_Inlet_TT101A) AND (rT_Inlet_TT101B <= rT_Inlet_TT101C)) OR 
          ((rT_Inlet_TT101B <= rT_Inlet_TT101A) AND (rT_Inlet_TT101B >= rT_Inlet_TT101C)) THEN
        rVoted_T_Inlet := rT_Inlet_TT101B;
    ELSE
        rVoted_T_Inlet := rT_Inlet_TT101C;
    END_IF;
ELSIF (NOT bFail_T_In_A) AND (NOT bFail_T_In_B) THEN
    rVoted_T_Inlet := (rT_Inlet_TT101A + rT_Inlet_TT101B) * 0.5;
ELSIF (NOT bFail_T_In_B) AND (NOT bFail_T_In_C) THEN
    rVoted_T_Inlet := (rT_Inlet_TT101B + rT_Inlet_TT101C) * 0.5;
ELSIF (NOT bFail_T_In_A) AND (NOT bFail_T_In_C) THEN
    rVoted_T_Inlet := (rT_Inlet_TT101A + rT_Inlet_TT101C) * 0.5;
ELSIF (NOT bFail_T_In_A) THEN
    rVoted_T_Inlet := rT_Inlet_TT101A;
ELSIF (NOT bFail_T_In_B) THEN
    rVoted_T_Inlet := rT_Inlet_TT101B;
ELSIF (NOT bFail_T_In_C) THEN
    rVoted_T_Inlet := rT_Inlet_TT101C;
ELSE
    rVoted_T_Inlet := 32.5; (* Fallback above critical temp *)
END_IF;

(* --- Mass Flow Rate 2oo3 Voting (FT-101A/B/C) --- *)
bFail_M_Fl_A := (rM_Flow_FT101A < 0.0) OR (rM_Flow_FT101A > 350.0);
bFail_M_Fl_B := (rM_Flow_FT101B < 0.0) OR (rM_Flow_FT101B > 350.0);
bFail_M_Fl_C := (rM_Flow_FT101C < 0.0) OR (rM_Flow_FT101C > 350.0);

IF (NOT bFail_M_Fl_A) AND (NOT bFail_M_Fl_B) AND (NOT bFail_M_Fl_C) THEN
    IF ((rM_Flow_FT101A >= rM_Flow_FT101B) AND (rM_Flow_FT101A <= rM_Flow_FT101C)) OR 
       ((rM_Flow_FT101A <= rM_Flow_FT101B) AND (rM_Flow_FT101A >= rM_Flow_FT101C)) THEN
        rVoted_M_Flow := rM_Flow_FT101A;
    ELSIF ((rM_Flow_FT101B >= rM_Flow_FT101A) AND (rM_Flow_FT101B <= rM_Flow_FT101C)) OR 
          ((rM_Flow_FT101B <= rM_Flow_FT101A) AND (rM_Flow_FT101B >= rM_Flow_FT101C)) THEN
        rVoted_M_Flow := rM_Flow_FT101B;
    ELSE
        rVoted_M_Flow := rM_Flow_FT101C;
    END_IF;
ELSIF (NOT bFail_M_Fl_A) AND (NOT bFail_M_Fl_B) THEN
    rVoted_M_Flow := (rM_Flow_FT101A + rM_Flow_FT101B) * 0.5;
ELSIF (NOT bFail_M_Fl_B) AND (NOT bFail_M_Fl_C) THEN
    rVoted_M_Flow := (rM_Flow_FT101B + rM_Flow_FT101C) * 0.5;
ELSIF (NOT bFail_M_Fl_A) AND (NOT bFail_M_Fl_C) THEN
    rVoted_M_Flow := (rM_Flow_FT101A + rM_Flow_FT101C) * 0.5;
ELSE
    rVoted_M_Flow := 120.0;
END_IF;

(* --- Rotor Speed 2oo3 Voting (ST-101A/B/C) --- *)
bFail_Speed_A := (rRotorSpeed_ST101A < 0.0) OR (rRotorSpeed_ST101A > 60000.0);
bFail_Speed_B := (rRotorSpeed_ST101B < 0.0) OR (rRotorSpeed_ST101B > 60000.0);
bFail_Speed_C := (rRotorSpeed_ST101C < 0.0) OR (rRotorSpeed_ST101C > 60000.0);

IF (NOT bFail_Speed_A) AND (NOT bFail_Speed_B) AND (NOT bFail_Speed_C) THEN
    IF ((rRotorSpeed_ST101A >= rRotorSpeed_ST101B) AND (rRotorSpeed_ST101A <= rRotorSpeed_ST101C)) OR 
       ((rRotorSpeed_ST101A <= rRotorSpeed_ST101B) AND (rRotorSpeed_ST101A >= rRotorSpeed_ST101C)) THEN
        rVoted_Speed := rRotorSpeed_ST101A;
    ELSIF ((rRotorSpeed_ST101B >= rRotorSpeed_ST101A) AND (rRotorSpeed_ST101B <= rRotorSpeed_ST101C)) OR 
          ((rRotorSpeed_ST101B <= rRotorSpeed_ST101A) AND (rRotorSpeed_ST101B >= rRotorSpeed_ST101C)) THEN
        rVoted_Speed := rRotorSpeed_ST101B;
    ELSE
        rVoted_Speed := rRotorSpeed_ST101C;
    END_IF;
ELSIF (NOT bFail_Speed_A) AND (NOT bFail_Speed_B) THEN
    rVoted_Speed := (rRotorSpeed_ST101A + rRotorSpeed_ST101B) * 0.5;
ELSE
    rVoted_Speed := rRotorSpeed_ST101A;
END_IF;

(* --- Radial Vibration Maximum Peak Selection (VT-101A/B/C) --- *)
(* Vibration protection employs 1oo3 high-select for conservative mechanical protection *)
rVoted_Vib := rVib_Radial_VT101A;
IF rVib_Radial_VT101B > rVoted_Vib THEN rVoted_Vib := rVib_Radial_VT101B; END_IF;
IF rVib_Radial_VT101C > rVoted_Vib THEN rVoted_Vib := rVib_Radial_VT101C; END_IF;

(* Assign Primary Voted Pipeline Outputs *)
rEffectiveSpeed     := rVoted_Speed;
rEffectiveMassFlow  := rVoted_M_Flow;
rEffectiveVibration := rVoted_Vib;

(* Compressor Total Pressure Ratio Pi = P_dis / P_suc *)
IF rVoted_P_Suction > 5.0 THEN
    rPressureRatio := rVoted_P_Discharge / rVoted_P_Suction;
ELSE
    rPressureRatio := 1.0;
END_IF;

(* ---------------------------------------------------------------------------------------------------
   STAGE 2: SUPERCRITICAL CO2 (sCO2) REAL-GAS THERMODYNAMICS & DENSITY
   Calculates fluid compressibility factor Z and density near the critical point
   (T_c = 30.98 deg C / 304.13 K, P_c = 73.77 bar) using modified Span-Wagner virial truncation.
   --------------------------------------------------------------------------------------------------- *)
VAR_TEMP
    rT_Abs_K    : REAL;
    rT_Reduced  : REAL;
    rP_Reduced  : REAL;
    rDeltaTr    : REAL;
END_VAR;

rT_Abs_K   := rVoted_T_Inlet + 273.15;
rT_Reduced := rT_Abs_K / rT_Critical_K;
rP_Reduced := rVoted_P_Suction / rP_Critical_Bar;
rDeltaTr   := rT_Reduced - 1.0;

(* Real-Gas Compressibility Factor Approximation: Z(Pr, Tr) *)
IF (rT_Reduced > 0.95) AND (rP_Reduced > 0.90) THEN
    (* Sharp drop in Z near pseudo-critical line *)
    rCompressibility_Z := 0.280 + (0.550 * rDeltaTr * rDeltaTr) + (0.045 * (rP_Reduced - 1.0));
    IF rCompressibility_Z < 0.20 THEN
        rCompressibility_Z := 0.20;
    ELSIF rCompressibility_Z > 0.95 THEN
        rCompressibility_Z := 0.95;
    END_IF;
ELSE
    rCompressibility_Z := 0.85;
END_IF;

(* Real-gas density rho = (P * 10^5) / (Z * R_co2 * T) in [kg/m^3] *)
IF (rCompressibility_Z > 0.05) AND (rT_Abs_K > 200.0) THEN
    rFluidDensity_Inlet := (rVoted_P_Suction * 100000.0) / (rCompressibility_Z * rGasConstant_R * rT_Abs_K);
ELSE
    rFluidDensity_Inlet := 450.0; (* Reference supercritical liquid-like density *)
END_IF;

(* ---------------------------------------------------------------------------------------------------
   STAGE 3: DYNAMIC SURGE LIMIT LINE (SLL) & SURGE CONTROL LINE (SCL)
   Computes aerodynamic stall boundary as a function of speed ratio, pressure ratio, and fluid density.
   --------------------------------------------------------------------------------------------------- *)
VAR_TEMP
    rSpeedRatio : REAL;
    rHeadEquiv  : REAL;
END_VAR;

rSpeedRatio := rVoted_Speed / 45000.0; (* Normalized to design rated speed 45,000 rpm *)
IF rSpeedRatio < 0.10 THEN rSpeedRatio := 0.10; END_IF;

(* Equivalent polytropic aerodynamic head differential parameter *)
rHeadEquiv := (rPressureRatio - 1.0) * (rFluidDensity_Inlet / 500.0);
IF rHeadEquiv < 0.0 THEN rHeadEquiv := 0.0; END_IF;

(* Parabolic Surge Limit Line: m_dot_sll = k_surge * sqrt(HeadEquiv) * SpeedRatio *)
rSurgeFlowLimit := 38.5 * SQRT(rHeadEquiv) * (0.35 + 0.65 * rSpeedRatio);

(* Dynamic Safety Margin Bias based on machine acceleration and density gradients *)
IF rVoted_T_Inlet < 32.0 THEN
    rSurgeMarginBias := 5.0; (* Add 5% safety margin near pseudo-critical density instability *)
ELSE
    rSurgeMarginBias := 0.0;
END_IF;

(* Surge Control Line (SCL) Flow target: 15% nominal margin plus active dynamic bias *)
rSurgeControlFlow := rSurgeFlowLimit * (1.0 + ((rSafetyMarginTarget + rSurgeMarginBias) / 100.0));

(* Instantaneous Normalized Surge Margin Percentage S_m *)
IF rSurgeFlowLimit > 1.0 THEN
    rSurgeMargin := ((rVoted_M_Flow - rSurgeFlowLimit) / rSurgeFlowLimit) * 100.0;
ELSE
    rSurgeMargin := 100.0;
END_IF;

(* ---------------------------------------------------------------------------------------------------
   STAGE 4: PROACTIVE dP/dt & dm/dt SURGE ANTICIPATION (DERIVATIVE KICK)
   Detects rapid cycle impedance fluctuations, fast valve closures, or downstream pressure waves.
   --------------------------------------------------------------------------------------------------- *)
IF rDt_Seconds > 0.001 THEN
    rRate_dPi_dt := (rPressureRatio - rPrevPressureRatio) / rDt_Seconds;
    rRate_dm_dt  := (rVoted_M_Flow - rPrevMassFlow) / rDt_Seconds;
END_IF;
rPrevPressureRatio := rPressureRatio;
rPrevMassFlow      := rVoted_M_Flow;

(* Trigger fast surge anticipation if pressure ratio spikes or mass flow decelerates sharply *)
IF (rRate_dPi_dt > 1.8) OR (rRate_dm_dt < -45.0) OR (rSurgeMargin < 6.0) THEN
    bSurgeAnticipateActive := TRUE;
    rSurgeKickHoldVal      := 40.0; (* Immediate 40% open pre-stroke dump *)
END_IF;

(* Decay surge kick hold over time *)
tSurgeKickDecayTimer(IN := bSurgeAnticipateActive, PT := T#800MS);
IF tSurgeKickDecayTimer.Q THEN
    bSurgeAnticipateActive := FALSE;
    rSurgeKickHoldVal      := 0.0;
    tSurgeKickDecayTimer(IN := FALSE);
END_IF;

(* ---------------------------------------------------------------------------------------------------
   STAGE 5: PRINTED CIRCUIT HEAT EXCHANGER (PCHE) THERMAL GRADIENT & DELTA-P MONITOR
   Monitors microchannel diffusion bonds against high delta-P and cyclic thermal fatigue.
   --------------------------------------------------------------------------------------------------- *)
IF rDt_Seconds > 0.001 THEN
    (* Microchannel metal temperature rate in [deg C / min] *)
    rPcheThermalGradient := ((rPCHE_Core_WallTemp_TT205 - rPrev_PCHE_WallTemp) / rDt_Seconds) * 60.0;
END_IF;
rPrev_PCHE_WallTemp := rPCHE_Core_WallTemp_TT205;

(* First-order low pass filter on PCHE core differential pressure *)
rPcheCoreDeltaP_Filtered := rPcheCoreDeltaP_Filtered + 0.15 * (rPCHE_Core_DeltaP_PDT201 - rPcheCoreDeltaP_Filtered);

(* ---------------------------------------------------------------------------------------------------
   STAGE 6: STATE-SPACE MODEL PREDICTIVE OBSERVER & LQ CONTROL ENGINE
   Estimates unmeasured states and computes multivariable anti-surge & PCHE bypass modulation.
   States:
     x1 = Delta Pressure Ratio error
     x2 = SCL mass flow deficit [kg/s]
     x3 = PCHE thermal rate deviation [deg C/min]
   --------------------------------------------------------------------------------------------------- *)
rState_x1 := rPressureRatio - 2.85; (* Baseline cycle compression ratio *)
rState_x2 := rSurgeControlFlow - rVoted_M_Flow;
rState_x3 := ABS(rPcheThermalGradient) - 1.5;

(* Luenberger State-Space Observer Correction: x_hat = A*x_hat + B*u + L*(y - C*x_hat) *)
rStateHat_x1 := (a11 * rStateHat_x1 + a12 * rStateHat_x2 + a13 * rStateHat_x3) 
                + (b11 * (rRecircValveDemand / 100.0) + b12 * (rPcheBypassDemand / 100.0))
                + (l11 * (rState_x1 - rStateHat_x1) + l12 * (rState_x2 - rStateHat_x2));

rStateHat_x2 := (a21 * rStateHat_x1 + a22 * rStateHat_x2 + a23 * rStateHat_x3) 
                + (b21 * (rRecircValveDemand / 100.0) + b22 * (rPcheBypassDemand / 100.0))
                + (l21 * (rState_x1 - rStateHat_x1) + l22 * (rState_x2 - rStateHat_x2));

rStateHat_x3 := (a31 * rStateHat_x1 + a32 * rStateHat_x2 + a33 * rStateHat_x3) 
                + (b31 * (rRecircValveDemand / 100.0) + b32 * (rPcheBypassDemand / 100.0))
                + (l31 * (rState_x1 - rStateHat_x1) + l32 * (rState_x2 - rStateHat_x2));

(* Multivariable State Feedback Demand Calculation *)
rMPC_ASV_Demand  := -(k11 * rStateHat_x1 + k12 * rStateHat_x2 + k13 * rStateHat_x3) * 10.0;
rMPC_PCHE_Demand := -(k21 * rStateHat_x1 + k22 * rStateHat_x2 + k23 * rStateHat_x3) * 8.0;

(* Secondary PI Trim Loop for Anti-Surge Recirculation Valve *)
IF rVoted_M_Flow < rSurgeControlFlow THEN
    rPID_ASV_Integral := rPID_ASV_Integral + (rSurgeControlFlow - rVoted_M_Flow) * 0.45 * rDt_Seconds;
ELSE
    rPID_ASV_Integral := rPID_ASV_Integral - 0.25 * rDt_Seconds; (* Slow automatic reset bleed *)
END_IF;
IF rPID_ASV_Integral < 0.0 THEN rPID_ASV_Integral := 0.0; END_IF;
IF rPID_ASV_Integral > 100.0 THEN rPID_ASV_Integral := 100.0; END_IF;

(* Secondary PCHE Core Protection Override *)
IF rPcheCoreDeltaP_Filtered > 3.8 THEN
    rPID_PCHE_Integral := rPID_PCHE_Integral + (rPcheCoreDeltaP_Filtered - 3.8) * 12.0 * rDt_Seconds;
ELSIF ABS(rPcheThermalGradient) > 2.5 THEN
    rPID_PCHE_Integral := rPID_PCHE_Integral + (ABS(rPcheThermalGradient) - 2.5) * 5.0 * rDt_Seconds;
ELSE
    rPID_PCHE_Integral := rPID_PCHE_Integral - 1.5 * rDt_Seconds;
END_IF;
IF rPID_PCHE_Integral < 0.0 THEN rPID_PCHE_Integral := 0.0; END_IF;
IF rPID_PCHE_Integral > 100.0 THEN rPID_PCHE_Integral := 100.0; END_IF;

(* ---------------------------------------------------------------------------------------------------
   STAGE 7: COMPREHENSIVE ALARM & SAFETY INTERLOCK EVALUATION
   --------------------------------------------------------------------------------------------------- *)
dwAlarmWord := 16#00000000;

(* Emergency Stop Relay Check *)
IF NOT bEStop_SIL3 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000001;
END_IF;

(* Suction Pressure Below Critical Phase Boundary Trip *)
IF rVoted_P_Suction < 74.0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000002;
END_IF;

(* Discharge Pressure Maximum Overpressure Trip *)
IF rVoted_P_Discharge > 285.0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000004;
END_IF;

(* Inlet Temperature Low Risk of Liquid Droplet Condensation Trip *)
IF rVoted_T_Inlet < 31.0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000008;
END_IF;

(* Bearing Vibration Velocity Warnings and Trips *)
IF rVoted_Vib > 4.5 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000010;
END_IF;
IF rVoted_Vib > 7.1 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000020;
END_IF;

(* Surge Margin Critical Violation *)
IF rSurgeMargin < 3.0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000040;
END_IF;

(* Dynamic Fast Surge Anticipation Trigger Active *)
IF bSurgeAnticipateActive THEN
    dwAlarmWord := dwAlarmWord OR 16#00000080;
END_IF;

(* PCHE Differential Pressure Stress Warnings and Trips *)
IF rPcheCoreDeltaP_Filtered > 3.8 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000100;
END_IF;
IF rPcheCoreDeltaP_Filtered > 4.8 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000200;
END_IF;

(* PCHE Thermal Shock Rate Warning *)
IF ABS(rPcheThermalGradient) > 2.5 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000400;
END_IF;

(* Sensor Redundancy Status Alarms *)
IF (wTMR_SensorHealth AND 16#0011) <> 0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000800; (* Discrepancy detected *)
END_IF;
IF (wTMR_SensorHealth AND 16#0022) <> 0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00001000; (* Degraded 1oo2 mode *)
END_IF;
IF (wTMR_SensorHealth AND 16#00CC) <> 0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00002000; (* Critical sensor loss *)
END_IF;
IF bManualOverride THEN
    dwAlarmWord := dwAlarmWord OR 16#00004000;
END_IF;

(* Master Failsafe Trip Interlock Decision *)
bTripInterlock := (dwAlarmWord AND 16#0000022F) <> 0;

(* ---------------------------------------------------------------------------------------------------
   STAGE 8: MULTI-STAGE FINITE STATE MACHINE (FSM)
   --------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE: COLD IDLE / SHUTDOWN *)
        bSystemReady        := FALSE;
        rRecircValveDemand  := 100.0; (* Anti-surge valve fully open to prevent pressurization stall *)
        rPcheBypassDemand   := 100.0; (* PCHE bypass open to equalize pressure across cycle *)
        rPID_ASV_Integral   := 0.0;
        rPID_PCHE_Integral  := 0.0;

        IF bEnable AND (NOT bTripInterlock) AND bEStop_SIL3 THEN
            iState := 10;
        END_IF;

    10: (* STATE: PRE-CHARGE & INVENTORY PRESSURE EQUALIZATION *)
        bSystemReady        := FALSE;
        rRecircValveDemand  := 100.0;
        rPcheBypassDemand   := 60.0;

        (* Await supercritical inventory precharge pressure > 74.5 bar *)
        IF (rVoted_P_Suction >= 74.5) AND (rVoted_T_Inlet >= 32.0) THEN
            tStateTimer(IN := TRUE, PT := T#5S);
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

    20: (* STATE: CRITICAL POINT PROXIMITY & MACHINE STARTUP ARMING *)
        bSystemReady := TRUE;
        rRecircValveDemand := 80.0;
        rPcheBypassDemand  := 30.0;

        (* Check rotor spin-up past minimum operating threshold *)
        IF rVoted_Speed > 15000.0 THEN
            iState := 30; (* Transition to closed-loop active modulation *)
        END_IF;

    30: (* STATE: CLOSED-LOOP ACTIVE MODULATION (NORMAL OPERATION) *)
        bSystemReady := TRUE;

        IF bManualOverride THEN
            (* Operator Manual Takeover Mode *)
            rRecircValveDemand := rManualASV_Demand;
            rPcheBypassDemand  := rManualPCHE_Demand;
        ELSE
            (* Unified MPC + PI Trim Anti-Surge Demand *)
            rRecircValveDemand := rMPC_ASV_Demand + rPID_ASV_Integral + rSurgeKickHoldVal;
            (* Unified MPC + PI Core Protection Bypass Demand *)
            rPcheBypassDemand  := rMPC_PCHE_Demand + rPID_PCHE_Integral;
        END_IF;

        (* Clamp Final Valve Demands to Physical Range [0.0..100.0 %] *)
        IF rRecircValveDemand < 0.0 THEN rRecircValveDemand := 0.0; END_IF;
        IF rRecircValveDemand > 100.0 THEN rRecircValveDemand := 100.0; END_IF;
        IF rPcheBypassDemand < 0.0 THEN rPcheBypassDemand := 0.0; END_IF;
        IF rPcheBypassDemand > 100.0 THEN rPcheBypassDemand := 100.0; END_IF;

        (* Priority Dynamic State Transitions *)
        IF bTripInterlock THEN
            iState := 99; (* Fail-Safe Trip *)
        ELSIF bSurgeAnticipateActive OR (rSurgeMargin < 8.0) THEN
            iState := 40; (* Fast Surge Avoidance State *)
        ELSIF (ABS(rPcheThermalGradient) > 2.0) OR (rPcheCoreDeltaP_Filtered > 3.5) THEN
            iState := 50; (* PCHE Thermal Shock Mitigation *)
        ELSIF (wTMR_SensorHealth AND 16#00E6) <> 0 THEN
            iState := 80; (* Degraded Sensor Mode *)
        END_IF;

    40: (* STATE: TRANSIENT FAST SURGE RECOVERY & INJECTION *)
        bSystemReady := TRUE;
        (* Snap ASV to high recovery aperture immediately *)
        rRecircValveDemand := 75.0 + rSurgeKickHoldVal;
        IF rRecircValveDemand > 100.0 THEN rRecircValveDemand := 100.0; END_IF;
        rPcheBypassDemand  := rPcheBypassDemand + 15.0; (* Vent backpressure *)
        IF rPcheBypassDemand > 100.0 THEN rPcheBypassDemand := 100.0; END_IF;

        (* Recover back to active modulation once aerodynamic margin clears 15% *)
        IF (rSurgeMargin > 15.0) AND (NOT bSurgeAnticipateActive) THEN
            iState := 30;
        END_IF;

        IF bTripInterlock THEN iState := 99; END_IF;

    50: (* STATE: PCHE THERMAL STRESS MITIGATION BYPASS *)
        bSystemReady := TRUE;
        (* Prioritize opening CV-202 to divert hot gas stream and limit dT/dt *)
        rPcheBypassDemand := rPcheBypassDemand + 20.0 * rDt_Seconds;
        IF rPcheBypassDemand > 85.0 THEN rPcheBypassDemand := 85.0; END_IF;

        (* Keep anti-surge modulated based on mass flow *)
        rRecircValveDemand := rMPC_ASV_Demand + rPID_ASV_Integral;
        IF rRecircValveDemand < 5.0 THEN rRecircValveDemand := 5.0; END_IF;

        IF (ABS(rPcheThermalGradient) < 1.0) AND (rPcheCoreDeltaP_Filtered < 3.0) THEN
            iState := 30;
        END_IF;

        IF bTripInterlock THEN iState := 99; END_IF;

    80: (* STATE: DEGRADED INSTRUMENTATION HOLD & CONTROL *)
        bSystemReady := TRUE;
        (* Maintain conservative anti-surge safety bias of +10% flow *)
        rRecircValveDemand := rMPC_ASV_Demand + rPID_ASV_Integral + 10.0;
        IF rRecircValveDemand > 100.0 THEN rRecircValveDemand := 100.0; END_IF;
        rPcheBypassDemand  := rMPC_PCHE_Demand + rPID_PCHE_Integral;

        IF bTripInterlock THEN iState := 99; END_IF;
        IF (wTMR_SensorHealth AND 16#00EE) = 0 THEN
            iState := 30; (* Sensors restored *)
        END_IF;

    99: (* STATE: FAIL-SAFE TRIP & EMERGENCY DEPRESSURIZATION *)
        bSystemReady        := FALSE;
        rRecircValveDemand  := 100.0; (* Full open bypass to eliminate compression head *)
        rPcheBypassDemand   := 100.0; (* Full open to equalize cycle pressure differential *)
        rPID_ASV_Integral   := 0.0;
        rPID_PCHE_Integral  := 0.0;

        IF (NOT bTripInterlock) AND (NOT bEnable) THEN
            iState := 0; (* Reset sequence to cold idle *)
        END_IF;

ELSE
    iState := 99; (* Unhandled vector failsafe trip *)
END_CASE;

(* ---------------------------------------------------------------------------------------------------
   STAGE 9: OPERATIONAL STATUS WORD ENCODING
   --------------------------------------------------------------------------------------------------- *)
dwStatusWord := 16#00000000;
IF bSystemReady THEN dwStatusWord := dwStatusWord OR 16#00000001; END_IF;
IF (rVoted_P_Suction > 73.8) AND (rVoted_T_Inlet > 31.0) THEN dwStatusWord := dwStatusWord OR 16#00000002; END_IF;
IF rVoted_Speed > 5000.0 THEN dwStatusWord := dwStatusWord OR 16#00000004; END_IF;
IF iState = 30 THEN dwStatusWord := dwStatusWord OR 16#00000008; END_IF;
IF bSurgeAnticipateActive THEN dwStatusWord := dwStatusWord OR 16#00000010; END_IF;
IF iState = 40 THEN dwStatusWord := dwStatusWord OR 16#00000020; END_IF;
IF iState = 50 THEN dwStatusWord := dwStatusWord OR 16#00000040; END_IF;
IF iState = 80 THEN dwStatusWord := dwStatusWord OR 16#00000080; END_IF;
IF iState = 99 THEN dwStatusWord := dwStatusWord OR 16#00000100; END_IF;
IF bManualOverride THEN dwStatusWord := dwStatusWord OR 16#00000200; END_IF;

END_FUNCTION_BLOCK
